import{_ as n,C as t,o as r,c as o,E as i,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/verification-evidence-20260909/deterministic-conflict-figure.en.svg",f=JSON.parse('{"title":"Only the Note Changed. Why Did the Evaluation Pass Rate Flip?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Only the Note Changed. Why Did the Evaluation Pass Rate Flip?","date":"2026-09-09","published_date":"2026-09-09","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"Only the Note Changed. Why Did the Evaluation Pass Rate Flip?","summary":"A real aggregation function remained deterministic while a note decided which conflicting result survived. Stable output and justified judgment are separate requirements.","cover":"/assets/verification-evidence-20260909/01-deterministic-conflict.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments; not independent QA; dependency substitutions disclosed","pageClass":"verification-evidence-article","sources":["https://github.com/yzhao062/awesome-auditable-ai/commit/3df29d2ae81d550dbe72a8d4a46dc3267c627413"]},"headers":[],"relativePath":"en/engineering/2026-09-09-deterministic-conflict.md","filePath":"en/engineering/2026-09-09-deterministic-conflict.md","lastUpdated":1788930481000}'),h={name:"en/engineering/2026-09-09-deterministic-conflict.md"};function c(p,e,u,g,m,y){const a=t("ArticleCover"),s=t("ArticleTableScroll");return r(),o("div",null,[i(a,{image:"/assets/verification-evidence-20260909/01-deterministic-conflict.png",kicker:"Engineering · Experimental research",title:"Only the Note Changed. Why Did the Evaluation Pass Rate Flip?",summary:"A real aggregation function remained deterministic while a note decided which conflicting result survived. Stable output and justified judgment are separate requirements.",version:"2026-09-09",languageHref:"/zh/engineering/2026-09-09-deterministic-conflict",languageLabel:"中文"}),i(s,{language:"en"}),e[0]||(e[0]=d(`<h1 id="only-the-note-changed-why-did-the-evaluation-pass-rate-flip" tabindex="-1">Only the Note Changed. Why Did the Evaluation Pass Rate Flip? <a class="header-anchor" href="#only-the-note-changed-why-did-the-evaluation-pass-rate-flip" aria-label="Permalink to &quot;Only the Note Changed. Why Did the Evaluation Pass Rate Flip?&quot;">​</a></h1><p>Two evaluation records shared an ID. One said pass; the other said fail. We exchanged their notes, <code>a</code> and <code>b</code>, without changing either outcome. The summary&#39;s pass rate moved from 100% to 0%.</p><p>This was an isolated experiment against a real aggregation function, not a production scoring incident. Its eight existing tests still passed, including the test requiring identical output when input order changes.</p><p>The implementation was deterministic. What it lacked was a reason to treat its chosen record as the authoritative result.</p><h2 id="the-test-answered-a-narrower-question" tabindex="-1">The test answered a narrower question <a class="header-anchor" href="#the-test-answered-a-narrower-question" aria-label="Permalink to &quot;The test answered a narrower question&quot;">​</a></h2><p>CodeFlowMu is a local multi-agent collaboration system we are developing. An evaluation helper introduced in an August change aggregates outcome records. Its change record explicitly describes resolving duplicate identities through a content comparison, avoiding dependence on arrival order.</p><p>That is a useful goal. Filesystem enumeration and asynchronous completion should not determine an evaluation. But a repeatable choice is not necessarily a justified one.</p><p>The conflict test submits the same records in both orders and checks equality. It does not require preservation of both claims or an explicit disputed result. Consistently discarding one side satisfies the assertions.</p><p>The missing contract concerns identity: does the same ID with different content represent a repeated observation, or a conflict?</p><h2 id="how-a-note-acquired-authority" tabindex="-1">How a note acquired authority <a class="header-anchor" href="#how-a-note-acquired-authority" aria-label="Permalink to &quot;How a note acquired authority&quot;">​</a></h2><p>We imported the actual <code>summarizeEvalOutcomes</code> function and supplied synthetic records:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The function groups by identity, serializes each complete raw record with sorted keys, and chooses the lexicographically smaller representation. The note participates in that comparison before the status. Swapping the notes changes the selected result.</p><p>Nothing establishes that the selected record is newer, better supported, or an authorized correction. The final summary retains only ID, name, and status, concealing the competing claim.</p><h2 id="controls-matter" tabindex="-1">Controls matter <a class="header-anchor" href="#controls-matter" aria-label="Permalink to &quot;Controls matter&quot;">​</a></h2><p>We ran eight cases in two separate Node processes, also reversing every input. These are function outputs, not estimates of model reliability.</p><table tabindex="0"><thead><tr><th>Synthetic condition</th><th style="text-align:right;">Retained</th><th style="text-align:right;">Duplicates</th><th>Output</th></tr></thead><tbody><tr><td>Different IDs, one pass and one fail</td><td style="text-align:right;">2</td><td style="text-align:right;">0</td><td>50%</td></tr><tr><td>Same ID, identical pass records</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>100%</td></tr><tr><td>Same ID; pass note=a, fail note=b</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>100%</td></tr><tr><td>Same outcomes; notes exchanged</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>0%</td></tr><tr><td>Same ID, pass/fail without notes</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>0%</td></tr><tr><td>Same case_id, different run_id, no record ID</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td>100%</td></tr><tr><td>Same runs with separate record IDs</td><td style="text-align:right;">2</td><td style="text-align:right;">0</td><td>50%</td></tr><tr><td>ID present, outcome missing</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td><td>unknown=1; rate field 0</td></tr></tbody></table><p><img src="`+l+'" alt="Figure: schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence."></p><p><em>Figure 1. schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence.</em></p><p>Both rounds agreed. Identical replay is correctly deduplicated, so abandoning deduplication would miss the point. The issue is treating replay and contradictory claims as the same category.</p><p>The missing-outcome control is equally important: the function preserves <code>unknown</code>. Its rate includes that record in the denominator, producing zero; that does not establish a confirmed test failure.</p><h2 id="a-test-case-is-not-a-test-run" tabindex="-1">A test case is not a test run <a class="header-anchor" href="#a-test-case-is-not-a-test-run" aria-label="Permalink to &quot;A test case is not a test run&quot;">​</a></h2><p>The helper accepts <code>case_id</code> as an identity fallback and does not include <code>run_id</code>. Two observations of one case can therefore collapse when distinct record IDs are absent. With explicit record IDs, both observations survive.</p><p>This is an input-contract finding, not proof that production repeated runs were lost. Our source search found the helper and its tests, but no production consumer in the searched JavaScript and TypeScript roots.</p><p>Before asking how many repeated measurements establish stability, check that repetitions remain separate observations. An <a href="https://github.com/yzhao062/awesome-auditable-ai/commit/3df29d2ae81d550dbe72a8d4a46dc3267c627413" target="_blank" rel="noreferrer">awesome-auditable-ai curation commit</a> carefully narrowed claims about repeated-query research rather than endorsing a universal repeat count. We cite that editorial decision; we did not reproduce those statistical methods.</p><h2 id="what-should-enter-development-review" tabindex="-1">What should enter development review <a class="header-anchor" href="#what-should-enter-development-review" aria-label="Permalink to &quot;What should enter development review&quot;">​</a></h2><p>Three cases deserve distinct contracts: identical replay, conflicting content under one record identity, and separate runs of one test. Preserve conflicting sources and expose disagreement instead of selecting a business outcome by note order. “Failure wins” would still be an unsupported selection rule unless explicitly justified.</p><p>The local helper is now the subject of a development-review submission. Consumer reachability, compatibility, and whether to retain the helper come first; no production incident or completed fix is claimed.</p><p>The evidence covers one historical change record, the actual helper at <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>, and eight synthetic cases. See the accompanying <a href="https://joinwell52-ai.github.io/joinwell52/en/research/evidence/2026-09-09-verification-evidence" target="_blank" rel="noreferrer">evidence guide</a>. Product-source disclosure remains separately reviewed.</p><p>Determinism tells us whether an answer repeats. Conflict preservation tells us whether a single answer is justified at all.</p>',30))])}const v=n(h,[["render",c]]);export{f as __pageData,v as default};
